insert into public.communities (name, slug, description)
select p.name, p.slug, p.description
from proposed p
where not exists (
  select 1 from public.communities c
  where lower(c.name) = lower(p.name) or lower(c.slug) = lower(p.slug)
 )
on conflict do nothing;

commit;
